class TacticalOutdoorDomainValidator:
    """Validation engine and rule verifier for All-Weather Expeditionary Mountaineering & Tactical Survival Gear."""
    domain_key = "tactical_outdoor"
    total_specs_count = len(SPEC_SCHEMA_TACTICAL_OUTDOOR)

    @classmethod
    def validate_spec_entry(cls, spec_key, candidate_value):
        schema = SPEC_SCHEMA_TACTICAL_OUTDOOR.get(spec_key)
        if not schema:
            return False, "Unknown spec key"
        allowed = schema.get("allowed_values", [])
        if allowed and candidate_value not in allowed:
            return False, f"Value {candidate_value} not in allowed list"
        return True, "Valid"

    @classmethod
    def filter_by_display_group(cls, group_name):
        return {k: v for k, v in SPEC_SCHEMA_TACTICAL_OUTDOOR.items() if v.get("display_group") == group_name}

    @classmethod
    def get_filterable_specs(cls):
        return {k: v for k, v in SPEC_SCHEMA_TACTICAL_OUTDOOR.items() if v.get("is_filterable")}

